```python
class OrderedDictionary:
    def __init__(self):
        self.ordered_dict = {}

    def add(self, key, value):
        if key not in self.ordered_dict:
            self.ordered_dict[key] = value
        else:
            self.ordered_dict[key] = self.ordered_dict[key] + (value,)

def create_ordered_dict():
    return OrderedDictionary()

d = create_ordered_dict()
for i in range(1, 11):
    d.add(i, i + 9)
print(d.ordered_dict)
```

