import config from './jest.config.js';

const globalSetup = require('./globalSetup');

const testEnvironmentOptions = {
  url: 'http://localhost/',
};

const transformRegex = /\${(.*?)}/g;
const tsConfig = config.moduleFileExtensions.includes('ts') ? config.moduleFileExtensions[1] : config.moduleFileExtensions[2];

globalSetup();

module.exports = {
  globals: {
    ts-jest: {
      babel: true,
      tsConfig,
    },
  },
  testMatch: [
    'src/**/__tests__/**/*.{js,jsx,ts,tsx}',
    'src/**/*.{spec,test}.{js,jsx,ts,tsx}',
  ],
  transform,
  setupFilesAfterEnv,
};
