Title: Memory leak using unique pointer and polymorphism.
Body: <p>I know that <code>std::unique_ptr</code> doesn't guarantee memory safety and especially it is true in the case of circular dependency. However, in my case, I can't see it. <code>Child</code> contain <code>Parent</code>(or <code>SecondChild</code> in case of polymorphism), but neither of them contains <code>Child</code>.</p>
<p>Valgrind reports <code>4 bytes</code> lost so I suppose that <code>SecondChild</code> was not destroyed. My code really relies on polymorphism so I hope to get advice on refactoring that won't change <code>Parent*</code> in <code>Child</code>.</p>
<pre><code>#include &lt;iostream&gt;
#include &lt;memory&gt;
using namespace std;

struct Parent
{
    Parent() {
        cout &lt;&lt; &quot;Expr created&quot; &lt;&lt; endl;
    }

    ~Parent() {
        cout &lt;&lt; &quot;Expr destroyed&quot; &lt;&lt; endl;
    }
};

struct Child : public Parent 
{
    std::unique_ptr&lt;Parent&gt; content;
};

struct SecondChild : public Parent 
{
    int val;
};

std::unique_ptr&lt;Parent&gt; foo()
{
    auto test = make_unique&lt;Child&gt;();
    auto content_in_child = make_unique&lt;SecondChild&gt;();
    content_in_child-&gt;val = 4;
    test-&gt;content = std::move(content_in_child);
    return test;
}

int main()
{
    std::unique_ptr&lt;Parent&gt; high = foo();
    return 0;
}
</code></pre>

Answers:
None
```cpp
#include &lt;iostream&gt;
#include &lt;memory&gt;
using namespace std;

// Define a parent class with a destructor to print creation and destruction messages
struct Parent
{
    Parent() {
        cout &lt;&lt; &quot;Expr created&quot; &lt;&lt; endl;
    }

    ~Parent() {
        cout &lt;&lt; &quot;Expr destroyed&quot; &lt;&lt; endl;
    }
};

// Define a child class that inherits from the parent class
struct Child : public Parent 
{
    // Use a unique pointer to hold a pointer to a parent object
    std::unique_ptr&lt;Parent&gt; content;
};

// Define a second child class that also inherits from the parent class
struct SecondChild : public Parent 
{
    int val; // Note: This is not a child object, it's a separate entity
};

// Define a function that returns a unique pointer to a parent object
std::unique_ptr&lt;Parent&gt; foo()
{
    // Create a child object using make_unique
    auto test = make_unique&lt;Child&gt;();
    // Create a second child object
    auto content_in_child = make_unique&lt;SecondChild&gt;();
    // Set the value of the second child object
    content_in_child-&gt;val = 4;
    // Set the content pointer of the child object to the second child object
    test-&gt;content = std::move(content_in_child);
    return test;
}

int main()
{
    // Create a unique pointer to a parent object
    std::unique_ptr&lt;Parent&gt; high = foo();
    return 0;
}
```

